import os
from moler.util.moler_test import MolerTest  # type: ignore
from moler.exceptions import CommandFailure  # type: ignore
from taf.ul.sc.perf.tc import tc
from taf.ul.sc.perf.util.logger import log_debug_function_info
from taf.ul.sc.util.scp import Scp  # type: ignore
from taf.ul.sc.perf.tc.tc_helpers import get_absolute_path
from taf.ul.sc.perf.util.helpers import get_library_path


class BenchmarkStats(object):
    def __init__(self, device=None,
                 script_path=None,
                 script_target_path="/user/toor4nsn/",
                 logs_path="/tmp/benchmark/logs/"):
        """
        Benchmark stats collecting
        :param script_path: path to script
        :param script_target_path: path where script will be coped
        :param logs_path: path where logs are stored
        :param device: device object
        """

        self.script_path = self._get_script_path(script_path)
        self.script_target_path = script_target_path
        self.logs_path = logs_path
        self.log_dir = tc.output_dir
        self.device = device

    @log_debug_function_info()
    def scp_script_to_device(self):
        device_name = self.device.name
        ws_name = self.device.ws_name
        scp_obj = Scp(local_dir=os.path.dirname(self.script_path), source_file=os.path.basename(self.script_path),
                      remote_device_name=device_name,
                      remote_dir=self.script_target_path, hops=[ws_name],
                      )
        scp_obj.upload()

    @log_debug_function_info()
    def start_collecting(self, period=None):
        script_cmd = os.path.join(self.script_target_path, os.path.basename(self.script_path))
        script_cmd = 'sh {} -l {}'.format(script_cmd, self.logs_path)
        if period is not None:
            script_cmd = '{} -p {}'.format(script_cmd, str(period))

        self.device.run_script(script_cmd=script_cmd, additional_params="&>/dev/null &")

    @log_debug_function_info()
    def copy_stats(self):

        device_name = self.device.name
        ws_name = self.device.ws_name
        dest_path = os.path.join(self.log_dir, "debug", device_name, "benchmark")
        try:
            files = self.device.ls(self.logs_path)
            if len(files['files']) > 0:
                scp = Scp(local_dir=dest_path, source_file='*', remove_source_file=True, remote_device_name=device_name,
                          remote_dir=os.path.join(self.logs_path, 'procdump'), hops=[ws_name], timeout=120)
                scp.download()
        except CommandFailure:
            MolerTest.warning(msg="Cannot scp files.")

    @log_debug_function_info()
    def stop_collecting(self):
        benchmark_processes = self.device.get_pid_of_processes(os.path.basename(self.script_path))
        self.device.kill_process(processes=benchmark_processes)

    @staticmethod
    def _get_script_path(script_path):
        if script_path:
            script_path = get_absolute_path(script_path)
        else:
            script_path = os.path.join(get_library_path(), 'scripts', 'FZ_Benchmark.sh')

        return script_path
